  'restless|uneasy': 'uneasy は心が「不安な」。restless はじっとしていられず「そわそわした」',
  'restraint|self-control': 'restraint は「自制・抑制」。self-control は自分の感情を「抑える力」',
  'resurgence|revival': 'revival は「復活」。resurgence は勢いの「再び高まること」',
  'retail|wholesale': 'retail は客に直接売る「小売り」、wholesale は店にまとめて売る「卸売り」',
