  'reveal|uncover': 'uncover は調べて「暴く」や、ふたを「取る」。reveal は隠れていたことを「明らかにする」',
  'revenge|vengeance': 'revenge は自分のための「仕返し」（take revenge）。vengeance は激しい「復讐」のかたい語',
  'reverse|undo': 'undo は「元に戻す・取り消す」。reverse は決定や順番を「逆にする・くつがえす」',
  'revolve|rotate': 'rotate は自分の軸で「自転する・回る」。revolve はほかのものの周りを「回る・公転する」',
  'riches|wealth': 'wealth は「富・財産」のふつうの語。riches は「富」の古めかしい言い方で、複数形で使う',
  'rich|wealthy': 'rich は「金持ちの」のふつうの語で、「豊かな・濃い」の意味もある。wealthy は「裕福な」の少しかたい語',
  'right|wrong': 'right は「正しい」の意味で wrong（間違った）と反対。「右の」の意味の反対は left',
  'rip|sew': 'sew は「縫う」、rip は「(びりっと)裂く」',
