  'risky|safe': 'risky は「危険な」、safe は「安全な」',
  'roam|wander': 'wander はあてもなく「さまよう」。roam は広い範囲を「歩き回る」',
  'rob|steal': 'steal は物を「盗む」（steal 物 from 人）。rob は人や場所から「奪う」（rob 人 of 物）で、目的語が逆',
