  'sadness|sorrow': 'sadness は「悲しみ」のふつうの語。sorrow は長く続く「深い悲しみ」のかたい語',
  'sad|sorrowful': 'sad は「悲しい」のふつうの語。sorrowful は「悲しみに満ちた・悲しげな」かたい語',
  'safely|securely': 'safely は「安全に・無事に」。securely は外れないように「しっかりと」',
  'safe|secure': 'safe は危険がなく「安全な」。secure は守られていて「安心な・しっかりした」（a secure job）',
  'sagacity|wisdom': 'wisdom は「知恵」。sagacity は「賢明さ・洞察力」のかたい語',
  'sail|voyage': 'sail は「航海する」のふつうの語。voyage は名詞で長い「船旅・航海」',
  'saint|sinner': 'saint は「聖人」、sinner は「罪人」',
  'same|similar': 'similar は「似ている」（similar to）。same は「同じ」（the same as）',
  'sanctuary|shrine': 'shrine は神などをまつる「神社・聖堂」。sanctuary は神聖な「聖域」や、動物の「保護区」',
  'sandal|slipper': 'sandal は外で履く「サンダル」。slipper は室内で履く「スリッパ・室内ばき」',
  'saturate|soak': 'soak は「浸す・ずぶぬれにする」。saturate は「(これ以上入らないほど)いっぱいに染みこませる」かたい語',
  'savagely|violently': 'violently は「激しく」。savagely は「凶暴に・むごく」と強い',
  'save|waste': 'waste は「むだにする」、save は「節約する」',
  'scared|unafraid': 'scared は「怖がった」、unafraid は「恐れない」',
  'scare|startle': 'scare は「怖がらせる」。startle は急に「びっくりさせる」（怖がらせるとは限らない）',
