  'script|text': 'script は劇やスピーチの「台本・原稿」。text は本などの「本文・文章」',
  'seal|stamp': 'stamp は「切手」や押して付ける「印・スタンプ」。seal は書類に押す公式の「印章・印」や、「封」',
  'search|seek': 'search は場所の中を「探す」（search the room）。seek は「求める」のかたい語',
