  'sea|shore': 'shore は「岸」、sea は「海」',
  'secondary|subordinate': 'secondary は「二次的な・二番目の」。subordinate は「下位の・従属した」',
  'securely|tightly': 'tightly は「ぎゅっと」。securely は外れないように「しっかりと・安全に」',
