  'sensible|wise': 'wise は経験や知識があって「賢明な」。sensible は常識があって「分別のある」',
  'separate|split': 'split は縦に「割る」や、グループが「分裂する」。separate はくっついているものを「分ける・引き離す」',
  'separation|union': 'separation は「分離・別離」、union は「結合」',
