  'skinny|thin': 'thin は「やせた・薄い」と広く言う。skinny は「がりがりの」のくだけた語で、ズボンなどの「細身の」にも使う',
  'slender|slim': 'slim は「ほっそりした」の話し言葉。slender は「すらりとした」と、美しさをほめる感じがある',
