  'sorcerer|wizard': 'wizard は物語の「魔法使い」。sorcerer は悪い魔法を使うことが多い「魔術師」',
  'soul|spirit': 'spirit は「精神・元気・霊」と広く言う。soul は体に宿る「魂」で、心の奥深くの感じ',
  'sound unit|syllable': 'syllable は「音節」（母音を中心にした音のひとまとまり）。sound unit は「音の単位」と説明するときの言い方で、ふつうは syllable と言う',
  'sour|sweet': 'sweet は「甘い」、sour は「酸っぱい」。sweet-and-sour は「甘酸っぱい」',
  'sour|tart': 'sour は「酸っぱい」のふつうの語。tart は果物がよい意味で「酸味のある」ことも言い、言葉が「辛辣な」の意味もある',
  'spacious|vast': 'spacious は部屋などが「広々とした」。vast は土地や量が「広大な・ばく大な」',
