  'spatter|splash': 'splash は水を「バシャッとはねかける」。spatter は液体を「点々と飛び散らす」',
  'species|type': 'species は生物の「種」。type は「型・タイプ」と広く言う',
  'speedy|swift': 'speedy は仕事などが「迅速な」。swift は動きが「すばやい」のやや文学的な語',
