  'still|vibrate': 'vibrate は「振動する」、still は動詞で「静まる・止まる」（ふつうは形容詞「じっとした」や副詞「まだ」）',
  'stock|supply': 'stock は店や家にある「在庫・蓄え」。supply は必要に応じて出せる「供給（量）・蓄え」',
  'stormy|tempestuous': 'stormy は「嵐の」のふつうの語。tempestuous は「大荒れの」のかたい語で、恋などが「激しい」にも使う',
  'stormy|turbulent': 'stormy は天気が「嵐の」や、関係が「荒れた」。turbulent は空気や水が「乱れた」や、時代が「激動の」',
  'strained|tense': 'tense は人や場面が「張り詰めた・緊張した」。strained は関係が「ぎくしゃくした」や、笑顔が「無理をした」',
  'strand|thread': 'thread は「糸」。strand は糸や髪の「1本」',
